#define PCIEIP_REG_PCIER_TLDA0_RDFIFO_4_BB                                                                   0x000c4cUL //Access:R    DataWidth:0x20   // The five read registers give a total of 160 bits of data from the FIFO. The FIFO is read when PCIER_TLDA0_RDFIFO_4 is read every other time. Also, on the opposite reads of PCIER_TLDA0_RDFIFO_4, the data in these registers is advanced to the next half of the FIFO data. So when the first PCIER_TLDA0_RDFIFO_4 read occurs, data is read from the FIFO and bits [159:0] are in these registers. Next read of PCIER_TLDA0_RDFIFO_4, bits [319:160] are in these registers. If the FIFO location is not used, each register will read 0xbaddf1f0.
#define PCIEIP_REG_PCIER_TLDA0_RDFIFO_3_BB                                                                   0x000c50UL //Access:R    DataWidth:0x20   // Bits [127:96] of the current half-data from the FIFO
#define PCIEIP_REG_PCIER_TLDA0_RDFIFO_2_BB                                                                   0x000c54UL //Access:R    DataWidth:0x20   // Bits [95:64] of the current half-data from the FIFO
#define PCIEIP_REG_PCIER_TLDA0_RDFIFO_1_BB                                                                   0x000c58UL //Access:R    DataWidth:0x20   // Bits [63:32] of the current half-data from the FIFO
#define PCIEIP_REG_PCIER_TLDA0_RDFIFO_0_BB                                                                   0x000c5cUL //Access:R    DataWidth:0x20   // Bits [31:0] of the current half-data from the FIFO
#define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_BB                                                                    0x000c60UL //Access:RW   DataWidth:0x20   // Main status and control register for the second Transaction Layer Data Analyzer. Trigger and status shown in this register.
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_TL_TLDAFIFO_RADDR_BB                                                (0x7f<<0) // The current read address for the external FIFO
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_TL_TLDAFIFO_RADDR_BB_SHIFT                                          0
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_FIFO_RADDR_DWSEL_BB                                                 (0x1<<7) // When set, indicates that the lower 160 bits from the current FIFO read address are in the RDFIFO registers.
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_FIFO_RADDR_DWSEL_BB_SHIFT                                           7
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_FIFO_RDAUTOINC_BB                                                   (0x1<<8) // When set and in local mode, reads to PCIER_TLDA_RDFIFO_4 will automatically increment the read address.
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_FIFO_RDAUTOINC_BB_SHIFT                                             8
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LINK_SERIES_BB                                                      (0x1<<9) // When set, this indicates the FIFOs are linked in series to increase the depth of the FIFO.
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LINK_SERIES_BB_SHIFT                                                9
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LINK_PARA_BB                                                        (0x1<<10) // When set, this indicates the FIFOs are linked in parallel to increase the width of the FIFO.
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LINK_PARA_BB_SHIFT                                                  10
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_UI_PRETRIG_ALL_BB                                                   (0x1<<11) // Valid only when reading FIFOs from the user interface. When set, all pretrigger data is considered valid and will be present on the interface. Note that there is a bug in earlier versions of the TLDA that make this a write-only bit.
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_UI_PRETRIG_ALL_BB_SHIFT                                             11
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_UNUSED0_BB                                                          (0x1<<12) // 
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_UNUSED0_BB_SHIFT                                                    12
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_DATA_AT_TRIG_BB                                                     (0x1<<13) // When set after FIFO has triggered, indicates that data at the trigger has been collected (as opposed to filtered out based on indirect register settings).
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_DATA_AT_TRIG_BB_SHIFT                                               13
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LOCAL_MODE_BB                                                       (0x1<<14) // When set, indicates that the FIFO is operating in local mode - FIFO will be read from the registers. When cleared, indicates that the FIFO is operating through reads from the user interface.
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LOCAL_MODE_BB_SHIFT                                                 14
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_PRETRIG_CNT_BB                                                      (0x7f<<15) // The number of pre-trigger samples to keep. pretrig_cnt[6] is only valid when if there are two TLDA blocks and they are linked serially (extending the FIFO depth).
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_PRETRIG_CNT_BB_SHIFT                                                15
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_TRIG_ADDR_BB                                                        (0x7f<<22) // The FIFO write address at the time of the trigger. Use bit 13 of this register to determine if there was data collected at the time of the trigger.
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_TRIG_ADDR_BB_SHIFT                                                  22
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_PRETRIG_FULL_BB                                                     (0x1<<29) // Set if pretrigger data was expected and enough data samples were collected prior to the trigger
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_PRETRIG_FULL_BB_SHIFT                                               29
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LOCAL_TLDA_TRIGGERED_BB                                             (0x1<<30) // Indicates that the TLDA is triggered.  For the above two bits, 0b10 is ready but not triggered, 0b11 is actively collecting and triggered, and 0b01 is that the TLDA has collected all needed data.
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LOCAL_TLDA_TRIGGERED_BB_SHIFT                                       30
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LOCAL_TLDA_ACTIVE_BB                                                (0x1<<31) // When set by write, activates the TLDA logic. To retrigger, this must be cleared then set again.  When read, this indicates that the TLDA is active (waiting for a trigger).
  #define PCIEIP_REG_PCIER_TLDA1_CTLSTAT_LOCAL_TLDA_ACTIVE_BB_SHIFT                                          31
#define PCIEIP_REG_PCIER_TLDA1_IND_CTLSTAT_BB                                                                0x000c64UL //Access:RW   DataWidth:0x20   // Control and status register for indirect accesses.
  #define PCIEIP_REG_PCIER_TLDA1_IND_CTLSTAT_IND_WADDR_REG_BB                                                (0xff<<0) // The indirect write address register.
  #define PCIEIP_REG_PCIER_TLDA1_IND_CTLSTAT_IND_WADDR_REG_BB_SHIFT                                          0
