  #define PCIEIP_REG_DL_FIFO_TEST_D2TFIFO_TESTSIZE_BB                                                        (0x3ff<<10) // D2T FIFO Test Size. When bit d2tfifo_testsize_sel is set to '1', this value is used as the D2T FIFO size. This value must be set to less than or equal to the actual FIFO size. Furthermore, if DL and TL are asynchronous, this value must be a power of 2. It is for simulation purpose only.
  #define PCIEIP_REG_DL_FIFO_TEST_D2TFIFO_TESTSIZE_BB_SHIFT                                                  10
  #define PCIEIP_REG_DL_FIFO_TEST_RESERVED_BB                                                                (0x3ff<<20) // 
  #define PCIEIP_REG_DL_FIFO_TEST_RESERVED_BB_SHIFT                                                          20
  #define PCIEIP_REG_DL_FIFO_TEST_REPLAYFIFO_TESTSIZE_SEL_BB                                                 (0x1<<30) // Replay FIFO Test Size Select. When this bit is set to '1', the value in replayfifo_testsize will be used as Replay FIFO size. This is for simulation purpose only.
  #define PCIEIP_REG_DL_FIFO_TEST_REPLAYFIFO_TESTSIZE_SEL_BB_SHIFT                                           30
  #define PCIEIP_REG_DL_FIFO_TEST_D2TFIFO_TESTSIZE_SEL_BB                                                    (0x1<<31) // D2T FIFO Test Size Select. When this bit is set to '1', the value in d2tfifo_testsize will be used as D2T FIFO size. This is for simulation purpose only.
  #define PCIEIP_REG_DL_FIFO_TEST_D2TFIFO_TESTSIZE_SEL_BB_SHIFT                                              31
