#define PCIEIP_REG_MDIO_ADDR_BB                                                                              0x001100UL //Access:RW   DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_MDIO_ADDR_ADR_BB                                                                        (0xffff<<0) // This value controls the register index sent to on the MDIO bus connected to the PCIE Serdes block.
  #define PCIEIP_REG_MDIO_ADDR_ADR_BB_SHIFT                                                                  0
  #define PCIEIP_REG_MDIO_ADDR_PORT_BB                                                                       (0xf<<16) // This value controls port address sent to on the MDIO bus connected to the PCIE Serdes block.
  #define PCIEIP_REG_MDIO_ADDR_PORT_BB_SHIFT                                                                 16
  #define PCIEIP_REG_MDIO_ADDR_CMD_BB                                                                        (0xfff<<20) // A write of '0' to these bits causes no action and allows the address to be programmed in preparation for a write. A write of '1' on these bits initiates a read at the address and port specified.
  #define PCIEIP_REG_MDIO_ADDR_CMD_BB_SHIFT                                                                  20
#define PCIEIP_REG_MDIO_WR_DATA_BB                                                                           0x001104UL //Access:RW   DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_MDIO_WR_DATA_WDATA_REG_BB                                                               (0x7fffffff<<0) // This value will be the register data for write cycles.
  #define PCIEIP_REG_MDIO_WR_DATA_WDATA_REG_BB_SHIFT                                                         0
  #define PCIEIP_REG_MDIO_WR_DATA_CMD_BB                                                                     (0x1<<31) // This bit must be written as a '1' to initiate write cycle based ont the data in bits [15:0] and the mdio_addr value. When the write has completed, this bit will read as '0'.
  #define PCIEIP_REG_MDIO_WR_DATA_CMD_BB_SHIFT                                                               31
#define PCIEIP_REG_MDIO_RD_DATA_BB                                                                           0x001108UL //Access:R    DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_MDIO_RD_DATA_RDATA_REG_BB                                                               (0x7fffffff<<0) // After a read has been requested in the mdio_addr register, this area will return the MDIO data. This field is only valid if the CMD field is '1'.
  #define PCIEIP_REG_MDIO_RD_DATA_RDATA_REG_BB_SHIFT                                                         0
  #define PCIEIP_REG_MDIO_RD_DATA_CMD_BB                                                                     (0x1<<31) // This bit will read as '0' until a requested read of the PCIE serdes has completed, in which case, this bit will read as '1'. This bit is automatically cleared by a write to the mdio_addr register.
  #define PCIEIP_REG_MDIO_RD_DATA_CMD_BB_SHIFT                                                               31
#define PCIEIP_REG_ATE_TLP_HDR_0_BB                                                                          0x00110cUL //Access:RW   DataWidth:0x20   // In ATE test mode this register together with ate_tlp_hdr_1, ate_tlp_hdr_2, and ate_tlp_hdr_3 form the 128-bit header information that is sent to TL logic to build a TLP. The header information is passed to TL as is except the TAG (i.e. bits 47:40 in a non-posted request) and RTAG (i.e. bits 79:72 in a Completion request), which are incremented by one after each packet transfer.
#define PCIEIP_REG_ATE_TLP_HDR_1_BB                                                                          0x001110UL //Access:RW   DataWidth:0x20   // When a TLP is generated in ATE test mode, this register holds bits [63:32] of the header bus.
#define PCIEIP_REG_ATE_TLP_HDR_2_BB                                                                          0x001114UL //Access:RW   DataWidth:0x20   // When a TLP is generated in ATE test mode, this register holds bits [95:64] of the header bus.
#define PCIEIP_REG_ATE_TLP_HDR_3_BB                                                                          0x001118UL //Access:RW   DataWidth:0x20   // When a TLP is generated in ATE test mode, this register holds bits [127:96] of the header bus.
#define PCIEIP_REG_ATE_TLP_CFG_BB                                                                            0x00111cUL //Access:RW   DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_ATE_TLP_CFG_ATE_TLP_CNT_BB                                                              (0xff<<0) // ATE TLP Count. Specify the number of TLP's to be transferred. When ate_tlp_go is set to '1', the value in this field is loaded into an internal counter that is decremented by one as each TLP is completed. Reading this register always returns the internal counter.
  #define PCIEIP_REG_ATE_TLP_CFG_ATE_TLP_CNT_BB_SHIFT                                                        0
  #define PCIEIP_REG_ATE_TLP_CFG_ATE_NULLIFY_BB                                                              (0x1<<8) // ATE TLP Nullify. When this bit is set to '1', an internal signal is asserted together with the last data word to nullify the transaction (i.e. emulate user_tx_nullify).
  #define PCIEIP_REG_ATE_TLP_CFG_ATE_NULLIFY_BB_SHIFT                                                        8
  #define PCIEIP_REG_ATE_TLP_CFG_ATE_PAT_SEL_BB                                                              (0x7<<9) // ATE Pattern Select.
  #define PCIEIP_REG_ATE_TLP_CFG_ATE_PAT_SEL_BB_SHIFT                                                        9
  #define PCIEIP_REG_ATE_TLP_CFG_UNUSED0_BB                                                                  (0xf<<12) // 
  #define PCIEIP_REG_ATE_TLP_CFG_UNUSED0_BB_SHIFT                                                            12
  #define PCIEIP_REG_ATE_TLP_CFG_ATE_PAT_SEED_BB                                                             (0xff<<16) // ATE Pattern Seed. This field holds the first data byte of the first TLP payload generated in ATE test mode. The remaining data bytes are generated based on the setting of ate_pat_sel.
  #define PCIEIP_REG_ATE_TLP_CFG_ATE_PAT_SEED_BB_SHIFT                                                       16
#define PCIEIP_REG_ATE_TLP_CTL_BB                                                                            0x001120UL //Access:RW   DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_ATE_TLP_CTL_ATE_TLP_GO_BB                                                               (0x1<<0) // ATE TLP Go bit. When this bit is set to '1', the TX User Interface is bypassed and internal logic generates packets to TL logic. After all packets are transferred, this bit is reset to '0' by hardware.
  #define PCIEIP_REG_ATE_TLP_CTL_ATE_TLP_GO_BB_SHIFT                                                         0
  #define PCIEIP_REG_ATE_TLP_CTL_UNUSED0_BB                                                                  (0x7<<1) // 
  #define PCIEIP_REG_ATE_TLP_CTL_UNUSED0_BB_SHIFT                                                            1
  #define PCIEIP_REG_ATE_TLP_CTL_REG_TRX_CLR_RX_TLP_SB_BB                                                    (0x1<<4) // Clear RX TLP scoreboard logic bit. SW needs to read trx_reg_sb_op_done (bit[31]). If trx_reg_sb_op_done register value is 1, it indicates that HW is done comparing RX TLPs. SW needs to write reg_trx_clr_rx_tlp_sb to '1' which will clear trx_reg_sb_op_done (bit[31]), trx_reg_err_tlp_num(bits[27:20]), trx_reg_data_mismatch (bit[17]) and trx_reg_hdr_mismatch (bit[16]) registers. It is a self clearing bit.
  #define PCIEIP_REG_ATE_TLP_CTL_REG_TRX_CLR_RX_TLP_SB_BB_SHIFT                                              4
  #define PCIEIP_REG_ATE_TLP_CTL_UNUSED1_BB                                                                  (0x7ff<<5) // 
  #define PCIEIP_REG_ATE_TLP_CTL_UNUSED1_BB_SHIFT                                                            5
  #define PCIEIP_REG_ATE_TLP_CTL_TRX_REG_HDR_MISMATCH_BB                                                     (0x1<<16) // Header Mismatch. A value of '1' indicates that transmitted TLP header does not match with received TLP header. This bit can be cleared by writing '1' to reg_trx_clr_rx_tlp_sb (bit[4]).
  #define PCIEIP_REG_ATE_TLP_CTL_TRX_REG_HDR_MISMATCH_BB_SHIFT                                               16
  #define PCIEIP_REG_ATE_TLP_CTL_TRX_REG_DATA_MISMATCH_BB                                                    (0x1<<17) // Data Mismatch. A value of '1' indicates that transmitted TLP data do not match with received TLP data. This bit can be cleared by writing '1' to reg_trx_clr_rx_tlp_sb (bit[4]).
  #define PCIEIP_REG_ATE_TLP_CTL_TRX_REG_DATA_MISMATCH_BB_SHIFT                                              17
  #define PCIEIP_REG_ATE_TLP_CTL_UNUSED2_BB                                                                  (0x3<<18) // 
  #define PCIEIP_REG_ATE_TLP_CTL_UNUSED2_BB_SHIFT                                                            18
  #define PCIEIP_REG_ATE_TLP_CTL_TRX_REG_ERR_TLP_NUM_BB                                                      (0xff<<20) // Indicates erroneous (header/ data mismatch) TLP number. If more than one TLP has an error, value will be 0xF. When an ATE TLP packet transmission is initiated, HW transmits number of TLPs equal to ATE_TLP_CNT (bits[7:0] of ate_tlp_cfg - offset 0x111c). trx_reg_err_tlp_num indicates the number of TLP that has error. This register is cleared by writing '1' to reg_trx_clr_rx_tlp_sb (bit[4]).
  #define PCIEIP_REG_ATE_TLP_CTL_TRX_REG_ERR_TLP_NUM_BB_SHIFT                                                20
  #define PCIEIP_REG_ATE_TLP_CTL_UNUSED3_BB                                                                  (0x7<<28) // 
  #define PCIEIP_REG_ATE_TLP_CTL_UNUSED3_BB_SHIFT                                                            28
  #define PCIEIP_REG_ATE_TLP_CTL_TRX_REG_SB_OP_DONE_BB                                                       (0x1<<31) // Value of '1' indicates that number of TLPs received is equal to number of TLPs transmitted (ATE_TLP_CNT (bits[7:0] of ate_tlp_cfg - offset 0x111c). This register value needs to be ignored until user writes '1' to ATE_TLP_GO (bit[0] of ate_tlp_ctl - offset 0x1120) register.
  #define PCIEIP_REG_ATE_TLP_CTL_TRX_REG_SB_OP_DONE_BB_SHIFT                                                 31
