#define PCIEIP_REG_REG_PHY_CTL_0_BB                                                                          0x001800UL //Access:RW   DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_REG_PHY_CTL_0_DIRECTED_WIDTH_CHANGE_REQ_BB                                              (0x1<<0) // Request a width change (ie -make the link wider, if possible). Do not assert if the "other side" is not capable of upconfiguration.
