  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_FRAMERR_BB                                                   (0x1<<8) // Consider DLLP and TLP framing errors as errors when reporting physical layer errors
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_FRAMERR_BB_SHIFT                                             8
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_NOLOCK_BB                                                    (0x1<<9) // Consider loss of bit and symbol lock from the PCIe Serdes as errors reporting physical layer errors
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_NOLOCK_BB_SHIFT                                              9
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_SKEW_BB                                                      (0x1<<10) // Consider link skew errors as errors when reporting physical layer errors
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_SKEW_BB_SHIFT                                                10
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_BUFOVER_BB                                                   (0x1<<11) // Consider buffer overrun errors from the PCIe Serdes as errors when processing ordered sets, DLLPs, and TLPs BUG: do not use in EP/RC Ax cores
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_BUFOVER_BB_SHIFT                                             11
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_BUFUNDER_BB                                                  (0x1<<12) // Consider buffer underrun errors from the PCIe Serdes as errors when processing ordered sets, DLLPs, and TLPs BUG: do not use in EP/RC Ax cores
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_BUFUNDER_BB_SHIFT                                            12
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_DECODE_BB                                                    (0x1<<13) // Consider decode errors from the PCIe Serdes as errors when processing ordered sets, DLLPs, and TLPs BUG: do not use in EP/RC Ax cores
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_RXERR_IS_DECODE_BB_SHIFT                                              13
  #define PCIEIP_REG_REG_PHY_CTL_0_UNUSED_1_BB                                                               (0x3<<14) // 
