  #define PCIEIP_REG_REG_PHY_CTL_0_REG_MCP_MATCH_POL_BB                                                      (0x1<<16) // If set, all symbols of the Modified Compliance Pattern must be of the same polarity (no mixed polarity) for the receiver to lock
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_MCP_MATCH_POL_BB_SHIFT                                                16
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_MCP_MATCH_ERR_BB                                                      (0x1<<17) // If set, both error symbols must match in the received Modified Compliance Pattern before the value is reported
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_MCP_MATCH_ERR_BB_SHIFT                                                17
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_MCP_EXIT_BB                                                           (0x1<<18) // Directed exit from generating the Modified Compliance Pattern in Polling.Compliance if the Enter Compliance bit of the Link Control 2 register is not set
  #define PCIEIP_REG_REG_PHY_CTL_0_REG_MCP_EXIT_BB_SHIFT                                                     18
