  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_SET_COMPL_RECV_BB                                       (0x1<<2) // Loopback Master Set Compliance Receive. If this bit is set to '1', the Compliance Receive bit in TS1 is set to '1' when loopback master initiates the loopback operation. This feature allows Loopback Slave to enter Loopback.Active state without achieving symbol lock or block alignment.
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_SET_COMPL_RECV_BB_SHIFT                                 2
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_AUTO_COMPL_RECV_BB                                      (0x1<<3) // Loopback Master Automatically Set Compliance Receive. If this bit is set to '1', hardware automatically sets the Compliance Receive bit in TS1 to '1' during Loopback.Entry state when loopback is entered from Configuration.Linkwidth.Start state and Gen3 is the highest common speed.
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_AUTO_COMPL_RECV_BB_SHIFT                                3
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_FRC_SETTING_BB                                          (0x1<<4) // Loopback Master Force Setting. When loopback is entered from Recov.Idle state and this bit is set to '1', hardware applies the settings specified in lpbk_master_slave_setting and lpbak_master_tx_setting registers.
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_FRC_SETTING_BB_SHIFT                                    4
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_SKPOS_BB                                                (0x1<<5) // Loopback Master Skip Ordered Set. When this bit is set, SKP OS are periodically inserted to loopback data. If data is generated by PHY, MAC provides SKP OS to PHY using a req/ack handshake. If it is Gen3 and data is generated by PHY without framing, this bit is ignored.
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_SKPOS_BB_SHIFT                                          5
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_ONE_SKPOS_BB                                            (0x1<<6) // Loopback Master One Skip Ordered Set. PCIE Spec requires that in Gen3 loopback master inserts two SKIP ordered sets for each SKIP OS interval. For testing purpose, when this bit is set to '1', hardware inserts only one SKP OS for each interval.
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_ONE_SKPOS_BB_SHIFT                                      6
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_UNUSED_2_BB                                                         (0x1<<7) // 
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_UNUSED_2_BB_SHIFT                                                   7
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_PATTERN_BB                                              (0x1f<<8) // Loopback Master Pattern. This field specifies the data pattern to be transmitted during Loopback.Active state. 5'b00000: reserved  5'b00001: Serdes PRBS7 pattern  5'b00010: Serdes PRBS15 pattern  5'b00011: Serdes PRBS23 pattern  5'b00100: Serdes PRBS31 pattern  5'b00101: Serdes 1010 pattern  5'b00110: Serdes 1100 pattern  5'b00111: Serdes low frequency pattern  5'b01000: reserved  5'b01001: Serdes PRBS7 pattern (with framing for Gen3)  5'b01010: Serdes PRBS15 pattern (with framing for Gen3)  5'b01011: Serdes PRBS23 pattern (with framing for Gen3)  5'b01100: Serdes PRBS31 pattern (with framing for Gen3)  5'b01101: Serdes 1010 pattern (with framing for Gen3)  5'b01110: Serdes 1100 pattern (with framing for Gen3)  5'b01111: Serdes low frequency pattern (with framing for Gen3)  5'b10000: MAC Compliance pattern  5'b10001: MAC Modified Compliance pattern  Others : reserved
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_PATTERN_BB_SHIFT                                        8
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_UNUSED_1_BB                                                         (0x7<<13) // 
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_UNUSED_1_BB_SHIFT                                                   13
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_LEN_BB                                                  (0xffff<<16) // Loopback Master Length. This field specifies the length of the loopback operation in milliseconds. When it is set to '0', software has to clear the lpbk_master_ena bit to stop the operation. When it is set to a non-zero value, hardware automatically clears the lpbk_master_ena bit after the specified time.
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL0_LPBK_MASTER_LEN_BB_SHIFT                                            16
#define PCIEIP_REG_PL_LPBK_MASTER_CTL1_BB                                                                    0x001904UL //Access:RW   DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL1_LPBK_MASTER_ENTRY_TMOUT_BB                                          (0x7f<<0) // Loopback Master Entry Timeout. While in Loopback.Entry state, if Compliance Receive bit was not set in transmitting TS1 and Loopback Master doesn't receive the feedback from Loopback Slave, it will transition to Detect state after a specified time. This field specifies the timeout in milliseconds. The timeout value must be less than 100ms.
  #define PCIEIP_REG_PL_LPBK_MASTER_CTL1_LPBK_MASTER_ENTRY_TMOUT_BB_SHIFT                                    0
#define PCIEIP_REG_PL_LPBK_MASTER_STAT_BB                                                                    0x001908UL //Access:R    DataWidth:0x20   // The loopback status register is cleared when lpbk_master_ena goes from '0' to '1'.
  #define PCIEIP_REG_PL_LPBK_MASTER_STAT_LPBK_MASTER_STAT_BB                                                 (0x1<<0) // Loopback Master Status. This is the status of the last loopback operation. 1'b0: completed normally 1'b1: exited because of timeout during Loopback.Entry state
  #define PCIEIP_REG_PL_LPBK_MASTER_STAT_LPBK_MASTER_STAT_BB_SHIFT                                           0
#define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_BB                                                           0x00190cUL //Access:RW   DataWidth:0x20   // This register specifies the Slave's TX settings that Loopback Master will transmit in TS1 during Loopback.Entry state in following cases: 1. Entered from Configuration.Linkwidth.Start and changed to a new speed. 2. Entered from Recovery.Idle and bit lpbk_master_frc_setting is set to '1'. If data rate is Gen3, Loopback Master will automatically set EC field (i.e. TS1, byte6[1:0]) to 2'b10 or 2'b11 depending on whether it is EP or RC respectively.
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_RXPRESET_BB                                (0x7<<0) // Loopback Master TS1 Receiver Preset Hint. This value is sent in TS1, byte6[2:0] if current rate is Gen1/Gen2 and EQ TS1's are sent.
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_RXPRESET_BB_SHIFT                          0
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_TXPRESET_BB                                (0xf<<3) // Loopback Master TS1 Transmitter Preset. This value is sent in TS1, byte6[6:3] if the current rate is Gen3 or current rate is Gen1/2 and EQ TS1's are sent.
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_TXPRESET_BB_SHIFT                          3
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_USEPRESET_BB                               (0x1<<7) // Loopback Master TS1 Use Preset. This value is sent in TS1, byte6[7] if the current rate is Gen3.
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_USEPRESET_BB_SHIFT                         7
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_PRECURSOR_BB                               (0x3f<<8) // Loopback Master TS1 Pre-Cursor Coefficient. This value is sent in TS1, byte7[5:0] if the current rate is Gen3.
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_PRECURSOR_BB_SHIFT                         8
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_CURSOR_BB                                  (0x3f<<14) // Loopback Master TS1 Cursor Coefficient. This value is sent in TS1, byte8[5:0] if the current rate is Gen3.
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_CURSOR_BB_SHIFT                            14
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_POSTCURSOR_BB                              (0x3f<<20) // Loopback Master TS1 Post-cursor Coefficient. This value is sent in TS1, byte9[5:0] if the current rate is Gen3.
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_POSTCURSOR_BB_SHIFT                        20
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_G2_DEEMPH_BB                               (0x1<<26) // Loopback Master TS1 Selectable De-emphasis. This value is sent in TS1, byte4[6] if the highest common rate is Gen2.
  #define PCIEIP_REG_PL_LPBK_MASTER_SLAVE_SETTING_LPBK_MASTER_TS1_G2_DEEMPH_BB_SHIFT                         26
#define PCIEIP_REG_PL_LPBK_MASTER_TX_SETTING_BB                                                              0x001910UL //Access:RW   DataWidth:0x20   // This register specifies the Loopback Master TX settings in following cases: 1. Entered from Configuration.Linkwidth.Start and changed to a new speed. 2. Entered from Recovery.Idle and bit lpbk_master_frc_setting is set to '1'.
  #define PCIEIP_REG_PL_LPBK_MASTER_TX_SETTING_LPBK_MASTER_G3_TXDEEMPH_BB                                    (0x3ffff<<0) // Loopback Master Gen3 TX Deemphasis. This TX setting is used when loopback is in Gen3 rate.
  #define PCIEIP_REG_PL_LPBK_MASTER_TX_SETTING_LPBK_MASTER_G3_TXDEEMPH_BB_SHIFT                              0
  #define PCIEIP_REG_PL_LPBK_MASTER_TX_SETTING_LPBK_MASTER_G2_TXDEEMPH_BB                                    (0x3<<18) // Loopback Master Gen2 Deemphasis. This TX setting is used when loopback is in Gen2 rate. Notes that for Gen1 the TX deemphasis is always set to -3.5db.
  #define PCIEIP_REG_PL_LPBK_MASTER_TX_SETTING_LPBK_MASTER_G2_TXDEEMPH_BB_SHIFT                              18
#define PCIEIP_REG_PL_SW_LTSSM_CTL_BB                                                                        0x001930UL //Access:RW   DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_ENA_BB                                                         (0x1<<0) // Software LTSSM Enable. Setting this bit to '1' allows software to take control of the LTSSM.
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_ENA_BB_SHIFT                                                   0
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_DLYSTART_BB                                                    (0x1<<1) // Software LTSSM Delay Start. When this bit is set together with sw_ltssm_ena, hardware continues to operate as normal until LTSSM reaches to the state specified by sw_ltssm_topst and sw_ltssm_subst. Once software starts controlling LTSSM, it continues to do so until sw_ltssm_ena is reset to '0'. This feature allows software to control LTSSM in some certain states but not all.
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_DLYSTART_BB_SHIFT                                              1
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_UPDT_BB                                                        (0x1<<2) // Software LTSSM Update. Writing a '1' to this bit updates the internal software LTSSM state with the state specified by sw_ltssm_topst and sw_ltssm_subst. If software is in control, the new state will be applied to LTSSM. This bit is self-cleared, so reading always retuns '0'.
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_UPDT_BB_SHIFT                                                  2
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_LTSSM_TMOUT_DIS_BB                                                      (0x1<<3) // LTSSM Timeout Disable. When this bit is set to '1', all LTSSM timeouts are disabled.
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_LTSSM_TMOUT_DIS_BB_SHIFT                                                3
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_UNUSED0_BB                                                              (0xf<<4) // 
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_UNUSED0_BB_SHIFT                                                        4
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_SUBST_BB                                                       (0x1ff<<8) // Software LTSSM Sub-level State. This field specifies the state of the sub-level state machine that software wants LTSSM to enter. The updating sub-level SM is selected based on the top-level state.
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_SUBST_BB_SHIFT                                                 8
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_UNUSED1_BB                                                              (0x7<<17) // 
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_UNUSED1_BB_SHIFT                                                        17
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_TOPST_BB                                                       (0x1ff<<20) // Software LTSSM Top-level State. This field specifies the state of the top-level state machine that software wants LTSSM to enter.
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_TOPST_BB_SHIFT                                                 20
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_UNUSED2_BB                                                              (0x3<<29) // 
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_UNUSED2_BB_SHIFT                                                        29
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_INT_ENA_BB                                                     (0x1<<31) // Software LTSSM Internal Enable. This bit reflects the internal software LTSSM enable that is set to '1' only when S/W is actually in control of the LTSSM. If sw_ltssm_dlystart is '1', the internal enable is not set until LTSSM reaches the desired state.
  #define PCIEIP_REG_PL_SW_LTSSM_CTL_SW_LTSSM_INT_ENA_BB_SHIFT                                               31
#define PCIEIP_REG_PCIE_STATIS_CTL_BB                                                                        0x001940UL //Access:RW   DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_PCIE_STATIS_CTL_PCIE_STATIS_ENA_BB                                                      (0x1<<0) // PCIE Statistic Enable. Setting this bit to '1' enables the PCIE statistic collection. Hardware will count various things such as the number of TLP, DLLP, OS bytes transferred in both RX and TX direction, the number of detected errors etc. When this bit is reset to '0', the counting stops and software can read the results. This bit can be automatically cleared after the specified time if pcie_statis_len is non-zero. All statistic read-back registers are cleared when this bit transitions from '0' to '1'.
  #define PCIEIP_REG_PCIE_STATIS_CTL_PCIE_STATIS_ENA_BB_SHIFT                                                0
  #define PCIEIP_REG_PCIE_STATIS_CTL_UNUSED0_BB                                                              (0x7f<<1) // 
  #define PCIEIP_REG_PCIE_STATIS_CTL_UNUSED0_BB_SHIFT                                                        1
  #define PCIEIP_REG_PCIE_STATIS_CTL_PCIE_STATIS_LEN_BB                                                      (0xffffff<<8) // PCIE Statistic Length. This field specifies the PCIE statistic collection time in microseconds. When it is set to '0', software has to clear the pcie_statis_ena bit to stop the operation. When it is set to a non-zero value, hardware automatically clears the enable bit after the specified time.
  #define PCIEIP_REG_PCIE_STATIS_CTL_PCIE_STATIS_LEN_BB_SHIFT                                                8
#define PCIEIP_REG_PCIE_TXTLP_STATIS_LO_BB                                                                   0x001944UL //Access:R    DataWidth:0x20   // PCIE TX TLP Statistic Low 32 bits. This is the number of TLP bytes that have been trasmitted. It is cleared when pcie_statis_ena goes from '0' to '1'.
