  #define PCIEIP_REG_PCIE_TXDLLP_STATIS_HI_PCIE_TXDLLP_STATIS_HI_BB_SHIFT                                    0
#define PCIEIP_REG_PCIE_TXOS_STATIS_LO_BB                                                                    0x001954UL //Access:R    DataWidth:0x20   // PCIE TX Ordered Set Statistic Low 32 bits. This is the number of ordered set bytes that have been trasmitted. It is cleared when pcie_statis_ena goes from '0' to '1'.
#define PCIEIP_REG_PCIE_TXOS_STATIS_HI_BB                                                                    0x001958UL //Access:R    DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_PCIE_TXOS_STATIS_HI_PCIE_TXOS_STATIS_HI_BB                                              (0xff<<0) // PCIE TX Ordered Set Statistic High 8 bits. This is the number of ordered set bytes that have been trasmitted. It is cleared when pcie_statis_ena goes from '0' to '1'.
  #define PCIEIP_REG_PCIE_TXOS_STATIS_HI_PCIE_TXOS_STATIS_HI_BB_SHIFT                                        0
#define PCIEIP_REG_PCIE_RXTLP_STATIS_LO_BB                                                                   0x00195cUL //Access:R    DataWidth:0x20   // PCIE RX TLP Statistic Low 32 bits. This is the number of TLP bytes that have been received. It is cleared when pcie_statis_ena goes from '0' to '1'.
#define PCIEIP_REG_PCIE_RXTLP_STATIS_HI_BB                                                                   0x001960UL //Access:R    DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_PCIE_RXTLP_STATIS_HI_PCIE_RXTLP_STATIS_HI_BB                                            (0xff<<0) // PCIE RX TLP Statistic High 8 bits. This is the number of TLP bytes that have been received. It is cleared when pcie_statis_ena goes from '0' to '1'.
  #define PCIEIP_REG_PCIE_RXTLP_STATIS_HI_PCIE_RXTLP_STATIS_HI_BB_SHIFT                                      0
#define PCIEIP_REG_PCIE_RXDLLP_STATIS_LO_BB                                                                  0x001964UL //Access:R    DataWidth:0x20   // PCIE RX DLLP Statistic Low 32 bits. This is the number of DLLP bytes that have been received. It is cleared when pcie_statis_ena goes from '0' to '1'.
#define PCIEIP_REG_PCIE_RXDLLP_STATIS_HI_BB                                                                  0x001968UL //Access:R    DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_PCIE_RXDLLP_STATIS_HI_PCIE_RXDLLP_STATIS_HI_BB                                          (0xff<<0) // PCIE RX DLLP Statistic High 8 bits. This is the number of DLLP bytes that have been received. It is cleared when pcie_statis_ena goes from '0' to '1'.
  #define PCIEIP_REG_PCIE_RXDLLP_STATIS_HI_PCIE_RXDLLP_STATIS_HI_BB_SHIFT                                    0
#define PCIEIP_REG_PCIE_RXOS_STATIS_LO_BB                                                                    0x00196cUL //Access:R    DataWidth:0x20   // PCIE RX Ordered Set Statistic Low 32 bits. This is the number of ordered set bytes that have been received. It is cleared when pcie_statis_ena goes from '0' to '1'.
#define PCIEIP_REG_PCIE_RXOS_STATIS_HI_BB                                                                    0x001970UL //Access:R    DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_PCIE_RXOS_STATIS_HI_PCIE_RXOS_STATIS_HI_BB                                              (0xff<<0) // PCIE RX Ordered Set Statistic High 8 bits. This is the number of ordered set bytes that have been received. It is cleared when pcie_statis_ena goes from '0' to '1'.
  #define PCIEIP_REG_PCIE_RXOS_STATIS_HI_PCIE_RXOS_STATIS_HI_BB_SHIFT                                        0
#define PCIEIP_REG_PCIE_PLRXERR_STATIS_BB                                                                    0x001974UL //Access:R    DataWidth:0x20   // PL Receiver Error Statistic. Number of errors detected by Physical Layer Receiver. It is cleared when pcie_statis_ena goes from '0' to '1'.
#define PCIEIP_REG_PCIE_RXDLLPERR_STATIS_BB                                                                  0x001978UL //Access:R    DataWidth:0x20   // RX DLLP Error Statistic. Number of DLLP CRC errors detected by Data Link Layer. It is cleared when pcie_statis_ena goes from '0' to '1'.
#define PCIEIP_REG_PCIE_RXTLPERR_STATIS_BB                                                                   0x00197cUL //Access:R    DataWidth:0x20   // RX TLP Error Statistic. Number of TLP LCRC and sequence number errors detected by Data Link Layer. It is cleared when pcie_statis_ena goes from '0' to '1'.
#define PCIEIP_REG_LTSSM_STATIS_CTL_BB                                                                       0x0019a0UL //Access:RW   DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_LTSSM_STATIS_CTL_LTSSM_STATIS_ENA_BB                                                    (0x1<<0) // LTSSM Statistic Enable. Setting this bit to '1' enables the LTSSM statisic collection. When this bit is reset to '0', information is frozen so S/W can read the results. All statistic registers are reset when this bit transitions from '0' to '1'.
  #define PCIEIP_REG_LTSSM_STATIS_CTL_LTSSM_STATIS_ENA_BB_SHIFT                                              0
  #define PCIEIP_REG_LTSSM_STATIS_CTL_LTSSM_STATIS_AUTOINC_BB                                                (0x1<<1) // LTSSM Statistic Auto Increment. When this bit is set to '1', hardware automatically increases the ltssm_statis_rdaddr by 1 after register ltssm_statis_N is read.
  #define PCIEIP_REG_LTSSM_STATIS_CTL_LTSSM_STATIS_AUTOINC_BB_SHIFT                                          1
  #define PCIEIP_REG_LTSSM_STATIS_CTL_LTSSM_STATIS_RDADDR_BB                                                 (0x1<<2) // LTSSM Statistic Readback Address. ltssm_statis_0 to ltssm_statis_N are stored in FIFOs. This field indicates the current readback address of the LTSSM Statistic FIFO. Reading ltssm_statis_0 to ltssm_statis_N registers return the values stored at current address. Software writes to this field to specify the starting FIFO offset where it wants to read back LTSSM statistic data.
  #define PCIEIP_REG_LTSSM_STATIS_CTL_LTSSM_STATIS_RDADDR_BB_SHIFT                                           2
