  #define PCIEIP_REG_LTSSM_STATIS_0_EQ_PH0_TIME_BB                                                           (0xffff<<16) // Equalization Phase 0 Time. This field contains the time that LTSSM spent in Equalization Phase 0 state. The unit is microsecond.
  #define PCIEIP_REG_LTSSM_STATIS_0_EQ_PH0_TIME_BB_SHIFT                                                     16
#define PCIEIP_REG_LTSSM_STATIS_1_BB                                                                         0x0019a8UL //Access:R    DataWidth:0x20   // Multi Field Register.
