  #define PCIEIP_REG_LTSSM_STATIS_1_EQ_PH3_TIME_BB_SHIFT                                                     0
  #define PCIEIP_REG_LTSSM_STATIS_1_EQ_PH2_TIME_BB                                                           (0xffff<<16) // Equalization Phase 2 Time. This field contains the time that LTSSM spent in Equalization Phase 2 state. The unit is microsecond.
  #define PCIEIP_REG_LTSSM_STATIS_1_EQ_PH2_TIME_BB_SHIFT                                                     16
#define PCIEIP_REG_LTSSM_STATIS_2_BB                                                                         0x0019acUL //Access:R    DataWidth:0x20   // Multi Field Register.
  #define PCIEIP_REG_LTSSM_STATIS_2_PWR_ACK_TIME_BB                                                          (0xff<<0) // Power State Acknowledge Time. This field contains the time since power state changed to when Serdes acknowledged. The unit is microsecond.
  #define PCIEIP_REG_LTSSM_STATIS_2_PWR_ACK_TIME_BB_SHIFT                                                    0
