  #define ETH_RSFEC_REG_RS_FEC_STATUS_BYPASS_CORRECTION_K2_E5_SHIFT                                          0
  #define ETH_RSFEC_REG_RS_FEC_STATUS_BYPASS_INDICATION_K2_E5                                                (0x1<<1) // Indicates the ability to disable error propagation to the PCS layer.
