  #define NCSI_REG_SIDEBAND_ARB_ARB_BYPASS_SHIFT                                                             6
  #define NCSI_REG_SIDEBAND_ARB_ARB_AUTO_BYPASS                                                              (0x1<<7) // Setting this field to '1' causes the NCSI port to cut latency when forwarding a token.
