#define GRC_REG_OVERRIDE_WINDOW_MEM_SELF_INIT_START                                                          0x050000UL //Access:RW   DataWidth:0x1    // Reset the protection override window memory. When set to 1, protection override window memory self init starts.
#define GRC_REG_OVERRIDE_WINDOW_MEM_SELF_INIT_DONE                                                           0x050004UL //Access:R    DataWidth:0x1    // When = 1, the self init for the protection override window memory is done.
#define GRC_REG_RSV_ATTN_ACCESS_DATA_0                                                                       0x050040UL //Access:R    DataWidth:0x1c   // Holds the data regarding the last access that caused reserved address interrupt. Bits [22:0]:  Address (4 bytes resolution). Bits [23]:    Wr/rd. If = 1 it is write, If = 0 it is read. Bits [27:24]: Master. The decoding: 1 = pxp. 2 = mcp. 3 = msdm. 4 = psdm. 5 = ysdm. 6 = usdm. 7 = tsdm. 8 = xsdm. 9 = dbu. 10 = dmae.
#define GRC_REG_RSV_ATTN_ACCESS_DATA_1                                                                       0x050044UL //Access:R    DataWidth:0x13   // Holds the data regarding the last access that caused reserved address interrupt. Bits [3:0]: PF. Bits [11:4]: VF. Bit  [13:12]: Port. Bits [15:14]: Privilege. The decoding: 0 - VN: Virtualized NIC (Used for VF access). 1 - PDA: Physical Device Assignment (Assigned to VM-s) 2 - HV: HyperVisor (Assigned to HV). 3 - UN: Un-restricted Access. Bits [18:16]: Protection. Contains the value set by the master. The decoding: 3 - 0: Takes the default protection defined by the slave RF block. 4: Over-ride the target slave address attribute to VN PROTECTION. 5: Over-ride the target slave address attribute to VM PROTECTION. 6: Over-ride the target slave address attribute to HV PROTECTION. 7: Over-ride the target slave address attribute to UA PROTECTION.
#define GRC_REG_RSV_ATTN_ACCESS_VALID                                                                        0x050048UL //Access:RW   DataWidth:0x1    // When asserted, = 1, indicates that the rsv_attn_access_data_0 and rsv_attn_access_data_1 registers contain valid data. While asserted these registers will not latch new data in case the event happened again. Asserted by the hardware, de-asserted by the SW.
#define GRC_REG_TIMEOUT_ATTN_ACCESS_DATA_0                                                                   0x05004cUL //Access:R    DataWidth:0x1c   // Holds the data regarding the last access that caused timeout interrupt. Bits [22:0]:  Address (4 bytes resolution). Bit  [23]:    Wr/rd. If = 1 it is write, if = 0 it is read. Bits [27:24]: Master. The decoding: 1 = pxp. 2 = mcp. 3 = msdm. 4 = psdm. 5 = ysdm. 6 = usdm. 7 = tsdm. 8 = xsdm. 9 = dbu. 10 = dmae.
#define GRC_REG_TIMEOUT_ATTN_ACCESS_DATA_1                                                                   0x050050UL //Access:R    DataWidth:0x13   // Holds the data regarding the last access that caused timeout interrupt. Bits [3:0]: PF. Bits [11:4]: VF. Bit  [13:12]: Port. Bits [15:14]: Privilege. The decoding: 0 - VN: Virtualized NIC (Used for VF access). 1 - PDA: Physical Device Assignment (Assigned to VM-s) 2 - HV: HyperVisor (Assigned to HV). 3 - UN: Un-restricted Access. Bits [18:16]: Protection. Contains the value set by the master. The decoding: 3 - 0: Takes the default protection defined by the slave RF block. 4: Over-ride the target slave address attribute to VN PROTECTION. 5: Over-ride the target slave address attribute to VM PROTECTION. 6: Over-ride the target slave address attribute to HV PROTECTION. 7: Over-ride the target slave address attribute to UA PROTECTION.
#define GRC_REG_TIMEOUT_ATTN_ACCESS_VALID                                                                    0x050054UL //Access:RW   DataWidth:0x1    // When asserted, = 1, indicates that the timeout_attn_access_data_0 and timeout_attn_access_data_1 registers contain valid data. While asserted these registers will not latch new data in case the event happened again. Asserted by the hardware, de-asserted by the SW.
#define GRC_REG_PATH_ISOLATION_ERROR_DATA_0                                                                  0x050058UL //Access:R    DataWidth:0x1c   // Holds the data regarding the last access that caused path isolation interrupt. Bits [22:0]:  Address (4 bytes resolution). Bit  [23]:    Wr/rd. If = 1 it is write, if = 0 it is read. Bits [27:24]: Master. The decoding: 1 = pxp. 2 = mcp. 3 = msdm. 4 = psdm. 5 = ysdm. 6 = usdm. 7 = tsdm. 8 = xsdm. 9 = dbu. 10 = dmae.
#define GRC_REG_PATH_ISOLATION_ERROR_DATA_1                                                                  0x05005cUL //Access:R    DataWidth:0x13   // Holds the data regarding the last access that caused path isolation interrupt. Bits [3:0]: PF. Bits [11:4]: VF. Bit  [13:12]: Port. Bits [15:14]: Privilege. The decoding: 0 - VN: Virtualized NIC (Used for VF access). 1 - PDA: Physical Device Assignment (Assigned to VM-s) 2 - HV: HyperVisor (Assigned to HV). 3 - UN: Un-restricted Access. Bits [18:16]: Protection. Contains the value set by the master. The decoding: 3 - 0: Takes the default protection defined by the slave RF block. 4: Over-ride the target slave address attribute to VN PROTECTION. 5: Over-ride the target slave address attribute to VM PROTECTION. 6: Over-ride the target slave address attribute to HV PROTECTION. 7: Over-ride the target slave address attribute to UA PROTECTION.
#define GRC_REG_PATH_ISOLATION_ERROR_VALID                                                                   0x050060UL //Access:RW   DataWidth:0x1    // When asserted, = 1, indicates that the path_isolation_error_data_0 and path_isolation_error_data_1 registers contain valid data. While asserted these registers will not latch new data in case the event happened again. Asserted by the hardware, de-asserted by the SW.
#define GRC_REG_TRACE_FIFO_VALID_DATA                                                                        0x050064UL //Access:R    DataWidth:0x1    // If = 1, indicates that the trace FIFO contains at least one valid data.                           If = 0, indicates that the trace FIFO doeasn't contain any valid data.                          This register should be read before reading the GRC_REGISTERS_TRACE_FIFO,                           and only if the read value is 1, one read from the GRC_REGISTERS_TRACE_FIFO can be done.
#define GRC_REG_TRACE_FIFO                                                                                   0x050068UL //Access:WB_R DataWidth:0x34   // Each row in the FIFO contains data regarding previous GRC rd/wr access. This FIFO conatins 32 rows. Before each read from this register, the register GRC_REGISTERS_TRACE_FIFO_VALID_DATA should be read, and only if the read value is 1, this FIFO has at least one valid data, and this register can be read once. The data: Bits [22:0]:  Address (4 bytes resolution). Bits [23]:    Wr/rd. If = 1 it is write, if = 0 it is read. Bits [27:24]: PF. Bits [35:28]: VF. Bit  [37:36]: Port. Bits [39:38]: Privilege. The decoding: 0 - VN: Virtualized NIC (Used for VF access). 1 - PDA: Physical Device Assignment (Assigned to VM-s) 2 - HV: HyperVisor (Assigned to HV). 3 - UN: Un-restricted Access. Bits [42:40]: Protection. The decoding: 3 - 0: Takes the default protection defined by the slave RF block. 4: Over-ride the target slave address attribute to VN PROTECTION. 5: Over-ride the target slave address attribute to VM PROTECTION. 6: Over-ride the target slave address attribute to HV PROTECTION. 7: Over-ride the target slave address attribute to UA PROTECTION. Bits [46:43]: Master. The decoding: 1 = pxp. 2 = mcp. 3 = msdm. 4 = psdm. 5 = ysdm. 6 = usdm. 7 = tsdm. 8 = xsdm. 9 = dbu. 10 = dmae. Bits [51:47]: Error type. The decoding: 0 = no error (access to the slave block ended successfully). 1 = timeout event. 2 = Reserved address that is acknowledged by the GRC block due to address which doesn't belong to any block address domain. 4 = slave block access to reserved address error or write to read only register which is set by the slave block that the access was targeted for. 8 = slave block privilege (protection) error which is set by the slave block that the access was targeted for.        16 = path isolation error.
#define GRC_REG_TRACE_FIFO_SIZE                                                                              2
#define GRC_REG_TRACE_FIFO_ENABLE                                                                            0x050070UL //Access:RW   DataWidth:0x1    // If = 1, the trace fifo feature is enabled and write of GRC wr/rd accesses to the FIFO is done based on the different trace FIFO configurtaions.                          If = 0, the trace fifo feature is disabled and no writes are done to the FIFO.                          It is recommended to disable this feature before reading from the GRC_REGISTERS_TRACE_FIFO.
#define GRC_REG_TRACE_FIFO_MASTERS_SEL                                                                       0x050074UL //Access:RW   DataWidth:0xa    // Selects the masters that their accesses are written to the trace FIFO. The range can be from one master to all masters, all combinations. If = 1, the master is enabled and its accesses are written to the trace FIFO. If = 0, the master is masked, and its accesses are not written to the trace FIFO. The fields: Bit [0]: pxp. Bit [1]: mcp. Bit [2]: msdm. Bit [3]: psdm. Bit [4]: ysdm. Bit [5]: usdm Bit [6]: tsdm. Bit [7]: xsdm. Bit [8]: dbu. Bit [9]: dmae.
#define GRC_REG_TRACE_FIFO_ERROR_TYPE_SEL                                                                    0x050078UL //Access:RW   DataWidth:0x6    // Selects the accesses with error types that are written to the trace FIFO. The range can be all combinations. If = 1 the error is enabled, access with applicable error is written to the trace FIFO. If = 0 the error is masked, access with applicable error is not written to the trace FIFO. The fields: Bit [0]: no error. Bit [1]: timeout event. Bit [2]: GRC reserved address. Reserved address that is acknowledged by the GRC block due to address which doesnt belong to any block address domain. Bit [3]: slave block address error. Slave block address error (access to reserved address or write to read only register) which is set by the slave block that the access was targeted for. Bit [4]: slave block privilege (protection) error. Slave block privilege (protection) error which is set by the slave block that the access was targeted for. Bit [5]: path isolation error.
#define GRC_REG_TRACE_FIFO_WR_RD_SEL                                                                         0x05007cUL //Access:RW   DataWidth:0x2    // Selects if wr/rd type accesses are written to the trace FIFO. One or both types can be enabled. If = 1 the wr/rd access is enabled, wr/rd access is written to the trace FIFO. If = 0 the wr/rd access is masked, wr/rd access is not written to the trace FIFO. The fields: Bit [0]: wr. Bit [1]: rd.
#define GRC_REG_TRACE_FIFO_PF_SEL                                                                            0x050080UL //Access:RW   DataWidth:0x10   // Selects the PF for the accesses that are written to the trace FIFO. The range is from one PF to all PFs, all combinations. If = 1 the PF is enabled, access with the PF is written to the trace FIFO. If = 0 the PF is masked, access with the PF is not written to the trace FIFO. BB: only bits 0-7 are applicable. The fields: Bit [0]: PF #0. Bit [1]: PF #1.            Bit [2]: PF #2. Bit [3]: PF #3.  Bit [4]: PF #4. Bit [5]: PF #5.            Bit [6]: PF #6. Bit [7]: PF #7. Bit [8]: PF #8. Bit [9]: PF #9.            Bit [10]: PF #10. Bit [11]: PF #11. Bit [12]: PF #12. Bit [13]: PF #13.            Bit [14]: PF #14. Bit [15]: PF #15.
#define GRC_REG_TRACE_FIFO_VF_SEL                                                                            0x050084UL //Access:RW   DataWidth:0x1    // If = 1, selects only the VF in GRC_REG_TRACE_FIFO_VF for the accesses that are written to the trace FIFO. If = 0, accesses with all VFs are written to the trace FIFO.
#define GRC_REG_TRACE_FIFO_VF                                                                                0x050088UL //Access:RW   DataWidth:0x8    // The VF for the accesses that are written to the trace FIFO. Applicable only if GRC_REG_TRACE_FIFO_VF_SEL = 1. Value of all 1s is applicable and represents VF not valid. BB: only bits 0-6 are applicable.
#define GRC_REG_TRACE_FIFO_PORT_SEL                                                                          0x05008cUL //Access:RW   DataWidth:0x4    // Selects the ports for the accesses that are written to the trace FIFO. The range is from one port to all ports, all combinations. If = 1 the port is enabled, access with the port is written to the trace FIFO. If = 0 the port is masked, access with the port is not written to the trace FIFO. BB: only bits 0-1 are applicable. The fields: Bit [0]: port #0. Bit [1]: port #1.            Bit [2]: port #2. Bit [3]: port #3.
