  #define IGU_REG_DEBUG_RECORD_MASK_MIN_SB_EN_SHIFT                                                          9
#define IGU_REG_DEBUG_RECORD_MASK_MAX_SB                                                                     0x181560UL //Access:RW   DataWidth:0xa    // Multi Field Register.
