#define NIG_REG_LLH_ENG_CLS_TYPE                                                                             0x501b80UL //Access:RW   DataWidth:0x1    // Engine classification type.  0 selects connection-based classification.  1 selects the PF-based classification. This register is used only in the single-port with dual engine mode.
#define NIG_REG_LLH_ENG_CLS_TCP_4_TUPLE_SEARCH                                                               0x501b84UL //Access:RW   DataWidth:0x1    // TCP 4-tuple search for TCP packets.  Set this bit to use the TCP 4-tuple (TCP source and destination port numbers and IP source and destination IP addresses) as the hash string. This register is used only in the single-port with dual engine mode.
